class Solution {
public:
    int shipWithinDays(vector<int>& weights, int days) {
        int lo = *max_element(weights.begin(), weights.end());
        long long hi = 0;
        for (int w : weights) hi += w;
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            int need = 1;
            long long cur = 0;
            for (int w : weights) {
                if (cur + w > mid) {
                    need++;
                    cur = 0;
                }
                cur += w;
            }
            if (need <= days) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};
